          "quote": "(net (code \"31\") (name \"NET0046\") (node (ref \"U10\") (pin \"5\") (pinfunction \"LAN_PORT1_TX+\") (pintype \"bidirectional\")) (node (ref \"U11\") (pin \"7\") (pinfunction \"COL1\") (pintype \"output\")))"
